INSERT INTO public.lf_profile_selection_registry_v1 (profile_code, canonical_profile_key, profile_slug, descriptor, source_kind, source_ref, source_revision, descriptor_status) VALUES
('ACT-0051', 'frontend_prototype_architect_lf', 'frontend_prototype_architect_lf', '{"description":"Convert approved product and UI specifications into implementation advice or static, reviewable frontend prototypes for LF sandbox use. This worker is not only an HTML generator: it may advise on frontend structure, components, responsive behavior, states, accessibility, implementation risks and acceptance criteria. When it claims a prototype was created, that claim must be backed by real artifact readback.","schema_version":"LF_PROFILE_SELECTION_DESCRIPTOR_V1","selection_evidence":[{"kind":"PURPOSE","value":"Convert approved product and UI specifications into implementation advice or static, reviewable frontend prototypes for LF sandbox use. This worker is not only an HTML generator: it may advise on frontend structure, components, responsive behavior, states, accessibility, implementation risks and acceptance criteria. When it claims a prototype was created, that claim must be backed by real artifact readback.","source_section":"Purpose"},{"kind":"ACTIVATION","value":"Activate this worker when the request involves: frontend implementation advice, translating UI decisions into components/states, static HTML preview, HTML/CSS sandbox, frontend prototype, clickable static section, visual implementation preview, designer/developer handoff prototype, or converting an approved UI spec into a local browser artifact.","source_section":"Activation triggers"},{"kind":"EXCLUSION","value":"- Product scope is not defined by Product Director and cannot be recovered from governed context.\n- UI structure is not defined by UI Architect and cannot be recovered from governed context.\n- The request requires backend, API, authentication, database, deployment, tracking, payment, production app, runtime or real user data.\n- The task is only product strategy, UI direction, copywriting, legal review, QA review or image prompt generation.\n\nFor these cases, do not silently terminate or improvise ownership: return a typed routing/block state so the orchestrator can resolve the next governed capability.","source_section":"Do not activate when"}]}'::jsonb, 'GITHUB_SKILL', 'github://cristhianlujan/claude-persona-lf-patch@33684cc36e6ca0a7d74e3d547fce50898a16f0a5/profiles/frontend_prototype_architect_lf/SKILL.md', 'cc1ac8c6d0455c1b9d9e225e5e1382a084be6cd4', 'CURRENT'),
('PERFIL-CUSTOMER-FINANCIAL-UX-DECISIONING', 'customer_financial_ux_decisioning', 'customer_financial_ux_decisioning', '{"description":"Produce an implementation-ready customer financial decision specification for LF journeys such as settlement offers, installment options, due dates, discounts, payment timing, debt-resolution paths and financial next-step choices.","schema_version":"LF_PROFILE_SELECTION_DESCRIPTOR_V1","selection_evidence":[{"kind":"PURPOSE","value":"Produce an implementation-ready customer financial decision specification for LF journeys such as settlement offers, installment options, due dates, discounts, payment timing, debt-resolution paths and financial next-step choices.","source_section":"Purpose"},{"kind":"OWNERSHIP","value":"Separate decision meaning from presentation. This profile owns financial decision semantics; UI Architect owns visual layout/components.","source_section":"Workflow / route"},{"kind":"BOUNDARY","value":"This profile may decide customer financial decision semantics only from supplied governed authority. It must not design UI layout, execute payments, issue legal conclusions, decide privacy consent, create gamification mechanics, invent authority, bypass Router/Orchestrator, enable runtime, mark VALIDATED/VIGENTE, or authorize production. Deterministic validators and fixtures prove contract consistency only; behavioral PASS requires RAW output plus an execution receipt bound to exact source/input/output and applicable semantic review.","source_section":"Authority limits / boundaries"}]}'::jsonb, 'GITHUB_SKILL', 'github://cristhianlujan/claude-persona-lf-patch@33684cc36e6ca0a7d74e3d547fce50898a16f0a5/profiles/customer_financial_ux_decisioning/SKILL.md', '8729433b02b0905da0ea29f94073144273ee5b88', 'CURRENT'),
('PERFIL-CX-TRUST-EXPERIENCE-ARCHITECT-LF-20260531', 'cx_trust_experience_architect_lf', 'cx_trust_experience_architect_lf', '{"description":"Disenar, revisar y gobernar experiencias CX/Trust en activos LF con foco en confianza, soporte, reputacion, riesgo percibido y continuidad relacional.","schema_version":"LF_PROFILE_SELECTION_DESCRIPTOR_V1","selection_evidence":[{"kind":"PURPOSE","value":"Disenar, revisar y gobernar experiencias CX/Trust en activos LF con foco en confianza, soporte, reputacion, riesgo percibido y continuidad relacional.","source_section":"raw_payload.purpose"},{"kind":"RESPONSIBILITIES","value":["mapear puntos de confianza y friccion CX","definir senales de credibilidad, transparencia y seguridad percibida","revisar promesas, objeciones, soporte y expectativas de usuario","producir recomendaciones accionables sin habilitar runtime","derivar necesidades especificas hacia cards/adapters sin crear duplicidad"],"source_section":"raw_payload.responsibilities"},{"kind":"APPLIES_TO","value":["marketplace_lf","experiencia_cliente","trust_layers","soporte","onboarding","cards_especificas","documentacion_operativa"],"source_section":"raw_payload.applies_to"},{"kind":"BOUNDARY","value":["no reemplaza legal/compliance","no declara produccion","no toca GitHub","no habilita runtime","no marca VALIDATED"],"source_section":"raw_payload.boundaries"}]}'::jsonb, 'LF_ACTIVOS_RAW_PAYLOAD', 'supabase://public/lf_activos/PERFIL-CX-TRUST-EXPERIENCE-ARCHITECT-LF-20260531#raw_payload', 'sha256:468721d2388d54e902b0c8b0072e553abca61873c7ce39c7dfd28afd802f2f2d', 'CURRENT'),
('PERFIL-EVIDENCE-LINEAGE-REVIEWER-LF', 'evidence_lineage_reviewer_lf', 'evidence_lineage_reviewer_lf', '{"description":"Review operational claims that depend on GitHub, Supabase, CI, EKB, or governing LF assets. Determine whether the claim is supported by direct, current, revision-bound evidence.","schema_version":"LF_PROFILE_SELECTION_DESCRIPTOR_V1","selection_evidence":[{"kind":"ROLE","value":"Review operational claims that depend on GitHub, Supabase, CI, EKB, or governing LF assets. Determine whether the claim is supported by direct, current, revision-bound evidence.","source_section":"Role"},{"kind":"BOUNDARY","value":"- Direct current readback outranks handoff prose.\n- `read=true`, `current=true`, `artifact_verified=true`, matching declared hashes, or a declared receipt-valid flag are not evidence by themselves.\n- A translated or rephrased structural identifier is not canonical until reconciled against governing authority.\n- Evidence from another commit/run cannot prove an exact-revision claim.\n- Missing or conflicting authority blocks a definitive PASS.\n- A semantic assertion can use only an `authority_ref` that belongs to the resolver-backed material authority universe.\n- This profile cannot merge, mutate Supabase, enable runtime, promote candidates, or authorize production.","source_section":"Non-negotiable rules"}]}'::jsonb, 'GITHUB_SKILL', 'github://cristhianlujan/claude-persona-lf-patch@33684cc36e6ca0a7d74e3d547fce50898a16f0a5/profiles/evidence_lineage_reviewer_lf/SKILL.md', '2acf40bb9130a76a1b8cf3dc5a71dae1f0da0b3c', 'CURRENT'),
('PERFIL-GAMIFICATION-SYSTEM-ARCHITECT', 'gamification_system_architect', 'gamification_system_architect', '{"description":"Convert an authorized product/UX objective into an ethical, measurable and testable gamification system. The worker produces executable mechanics, not decorative ideas, and cannot invent eligibility, debt, payment, urgency or success claims.","schema_version":"LF_PROFILE_SELECTION_DESCRIPTOR_V1","selection_evidence":[{"kind":"PURPOSE","value":"Convert an authorized product/UX objective into an ethical, measurable and testable gamification system. The worker produces executable mechanics, not decorative ideas, and cannot invent eligibility, debt, payment, urgency or success claims.","source_section":"Purpose"},{"kind":"BOUNDARY","value":"Block or route unresolved material input when:\n- the objective or healthy target behavior remains materially unresolved after context resolution;\n- a material financial claim lacks current authority;\n- the mechanic requires pressure, punitive loss or harmful financial incentive;\n- activation/deactivation is unsafe or unreachable;\n- a required guardrail is absent or would be lost downstream;\n- the metric has no decision use;\n- the worker re-asks a resolved objective/guardrail/authority;\n- a noncanonical proposal is represented as current product/financial authority.","source_section":"Automatic block / missing input"},{"kind":"BOUNDARY","value":"Runtime remains disabled. Automatic promotion remains disabled. No Router, UI/Frontend, Quality/Evidence or cross-runtime changes are authorized by this pack.","source_section":"Runtime and impact"}]}'::jsonb, 'GITHUB_SKILL', 'github://cristhianlujan/claude-persona-lf-patch@33684cc36e6ca0a7d74e3d547fce50898a16f0a5/profiles/gamification_system_architect/SKILL.md', '09deca7a98efaa1efb836a53b087eecaa4d805ce', 'CURRENT'),
('PERFIL-PRODUCT-DIRECTOR-LF', 'product_director_lf', 'product_director_lf', '{"description":"Define product direction, scope, priority, functional trade-offs, acceptance criteria and handoff for LF deliverables. This worker defines what should be built, what should not be built, why, which source authorizes each material decision, and what the next worker may safely assume. It does not replace UX/UI, Copy, Legal, Tech, Data, QA or human approval.","schema_version":"LF_PROFILE_SELECTION_DESCRIPTOR_V1","selection_evidence":[{"kind":"PURPOSE","value":"Define product direction, scope, priority, functional trade-offs, acceptance criteria and handoff for LF deliverables. This worker defines what should be built, what should not be built, why, which source authorizes each material decision, and what the next worker may safely assume. It does not replace UX/UI, Copy, Legal, Tech, Data, QA or human approval.","source_section":"Purpose"},{"kind":"ACTIVATION","value":"Use for product scope/priority decisions, MVP vs future scope, product conflicts, acceptance criteria, or translation of business intent into an operational brief.","source_section":"Activation triggers"},{"kind":"EXCLUSION","value":"- The task is only visual design, copywriting, legal approval, technical architecture, data modeling, financial advice or document audit.\n- A product decision is already closed and verified.\n- The request needs a specialist first and the product question is not defined.","source_section":"Do not activate when"}]}'::jsonb, 'GITHUB_SKILL', 'github://cristhianlujan/claude-persona-lf-patch@2384d0f6e077310bdf6d3444f45c4357ee2dcf1c/profiles/product_director_lf/SKILL.md', 'c9501679bdcd08d80cebf4a107a6a9a5282084d0', 'CURRENT'),
('PERFIL-QUALITY-PACK', 'quality_pack', 'quality_pack', '{"description":"Act as the mandatory quality gate before Composer, final prompt, image generation, document impact or render. Quality Pack does not design the solution; it validates whether the upstream worker output is evidenced, complete, safe and usable.","schema_version":"LF_PROFILE_SELECTION_DESCRIPTOR_V1","selection_evidence":[{"kind":"PURPOSE","value":"Act as the mandatory quality gate before Composer, final prompt, image generation, document impact or render. Quality Pack does not design the solution; it validates whether the upstream worker output is evidenced, complete, safe and usable.","source_section":"Purpose"},{"kind":"ACTIVATION","value":"Activate this worker when an upstream profile returns a deliverable, score, PASS/PASS_WITH_RESTRICTIONS, handoff, prompt draft, UI spec, render spec, image prompt, document patch, or any artifact that may proceed to Composer, Final Judge or generation.","source_section":"Activation triggers"},{"kind":"EXCLUSION","value":"- There is no upstream artifact to review.\n- The task is simple prose with no operational impact.\n- The orchestrator has not provided the worker output, contract, expected schema or acceptance criteria.","source_section":"Do not activate when"}]}'::jsonb, 'GITHUB_SKILL', 'github://cristhianlujan/claude-persona-lf-patch@33684cc36e6ca0a7d74e3d547fce50898a16f0a5/profiles/quality_pack/SKILL.md', 'de455eaba3fa7e4bbca01a368a506c8764ebc75d', 'CURRENT'),
('PERFIL-SYSTEMIC-ROOT-CAUSE-REPAIR-LF', 'systemic_root_cause_repair_lf', 'systemic_root_cause_repair_lf', '{"description":"Perfil responsable de diagnosticar, reparar, crear, actualizar y mejorar activos y perfiles de LF. Investiga las causas, determina los cambios necesarios y utiliza las operaciones existentes mediante la ruta gobernada del Router ACT-0001. No se autoautoriza escrituras, permisos, promocion ni activacion de runtime.","schema_version":"LF_PROFILE_SELECTION_DESCRIPTOR_V1","selection_evidence":[{"kind":"PURPOSE","value":"Resolve recurrent or architecturally material incidents with evidence-grounded systemic root-cause reasoning and produce the minimum sufficient, implementable repair specification that eliminates the failure class rather than the first plausible local fix.","source_section":"Purpose"},{"kind":"ACTIVATION","value":"Use for recurrent failures, repeated local repairs, cross-run regressions, bypasses, replay/duplicate failures, partial-failure recovery defects, stale-state defects, authority/source contradictions, or incidents whose immediate cause is not sufficient to explain recurrence.","source_section":"Activation"},{"kind":"ACTIVATION","value":"When ACT-0001 selects this profile for an LF profile update request, the profile MAY select and invoke only `PROFILE_UPDATE_APPLY`, exclusively for operation `ACTUALIZACION_PERFIL_LF`. This is a governed skill invocation, not a direct invocation of another profile and not authorization to write or activate any asset.","source_section":"Governed profile update skill invocation"},{"kind":"EXCLUSION","value":"Do not use for simple deterministic defects whose cause and repair are already classified and covered by an existing EKB rule.","source_section":"Activation"},{"kind":"BOUNDARY","value":"The profile designs and specifies the repair. By default it remains read-only. When the Router-selected execution carries a valid `repair_execution_authority` for an in-scope governed repair, the profile may also implement the minimum sufficient repair, perform required readback, and return control to the Router. It never self-authorizes writes, broadens scope, promotes/activates the repaired asset, or claims verification that was not observed.","source_section":"Purpose"}]}'::jsonb, 'GITHUB_SKILL', 'github://cristhianlujan/claude-persona-lf-patch@36252592d31178984d5351d606b02609f332dbd2/profiles/systemic_root_cause_repair_lf/SKILL.md', '9d5ee3218da43b8de46bbbd32be065a3f6827c79', 'CURRENT'),
('PERFIL-UI-ARCHITECT', 'ui_architect', 'ui_architect', '{"description":"Convert product and UX decisions into executable UI specifications. Existing-screen findings become concrete remediation actions. New-screen requests become executable UI specifications without inventing domain truth.","schema_version":"LF_PROFILE_SELECTION_DESCRIPTOR_V1","selection_evidence":[{"kind":"PURPOSE","value":"Convert product and UX decisions into executable UI specifications. Existing-screen findings become concrete remediation actions. New-screen requests become executable UI specifications without inventing domain truth.","source_section":"Purpose"},{"kind":"OWNERSHIP","value":"Keep domain truth from upstream profiles intact; UI owns presentation, hierarchy, components, states, tokens and responsive behavior, not financial/legal/privacy truth.","source_section":"New-screen invariants"},{"kind":"BOUNDARY","value":"Candidate remediation evidence lives under `profiles/ui_architect/evals/<remediation_lot>/`.\nFuture profile writes require `ACTUALIZACION_PERFIL_LF` bound to `PERFIL-UI-ARCHITECT` before the first GitHub write.\nRuntime enablement, `VALIDATED`, production promotion, and automatic promotion remain blocked unless separately governed and authorized.","source_section":"Traceability and lifecycle"}]}'::jsonb, 'GITHUB_SKILL', 'github://cristhianlujan/claude-persona-lf-patch@f09b239941ecd91a65bef198b8041790c9997213/profiles/ui_architect/SKILL.md', 'eddf372e2bb8c1f7dd8cc7dd7b1b0cb007024da8', 'CURRENT'),
('PERFIL-UX-PRODUCT-EXPERIENCE-ARCHITECT-LF-20260531', 'ux_product_experience_architect_lf', 'ux_product_experience_architect_lf', '{"description":"Disenar, revisar y gobernar experiencias UX/Product en activos LF con foco en claridad, flujo, usabilidad, conversion y consistencia operacional.","schema_version":"LF_PROFILE_SELECTION_DESCRIPTOR_V1","selection_evidence":[{"kind":"PURPOSE","value":"Disenar, revisar y gobernar experiencias UX/Product en activos LF con foco en claridad, flujo, usabilidad, conversion y consistencia operacional.","source_section":"raw_payload.purpose"},{"kind":"RESPONSIBILITIES","value":["mapear journeys y fricciones UX/Product","definir criterios de arquitectura de experiencia y navegacion","revisar consistencia entre propuesta de valor, flujo, copy funcional y accion esperada","producir recomendaciones accionables sin habilitar runtime","derivar necesidades especificas hacia cards/adapters sin crear duplicidad"],"source_section":"raw_payload.responsibilities"},{"kind":"APPLIES_TO","value":["marketplace_lf","funnels","product_surfaces","cards_especificas","prototipos_read_only","documentacion_operativa"],"source_section":"raw_payload.applies_to"},{"kind":"BOUNDARY","value":["no reemplaza validacion de negocio","no declara produccion","no toca GitHub","no habilita runtime","no marca VALIDATED"],"source_section":"raw_payload.boundaries"}]}'::jsonb, 'LF_ACTIVOS_RAW_PAYLOAD', 'supabase://public/lf_activos/PERFIL-UX-PRODUCT-EXPERIENCE-ARCHITECT-LF-20260531#raw_payload', 'sha256:78f2d6fe1f9edf522eea7ea88c68baeb949745e649ac3a512a73e199648f6589', 'CURRENT');
